const $=id=>document.getElementById(id);let session=[],position=0,correct=0,answered=false;const key='security-quest-v1';let history={};try{history=JSON.parse(localStorage.getItem(key)||'{}')}catch{};
function save(){try{localStorage.setItem(key,JSON.stringify(history))}catch{}}
function stats(){let entries=Object.values(history);$('stats').textContent=`収録 ${questions.length} 問 ｜ 回答履歴 ${entries.reduce((a,b)=>a+b.attempts,0)} 回 ｜ 間違えた問題 ${entries.filter(x=>x.wrong>0).length} 件`}
function show(id){['home','game','result'].forEach(x=>$(x).classList.toggle('hidden',x!==id))}
function start(){let mode=$('mode').value;let pool=questions.filter(q=>mode==='all'||(mode==='missed'?history[q.id]?.wrong>0:q.mode===mode));if(!pool.length){$('status').textContent='該当する問題がありません。別のモードを選んでください。';return}session=pool.sort(()=>Math.random()-.5).slice(0,Number($('count').value)||5);position=0;correct=0;$('status').textContent='';show('game');render()}
function render(){answered=false;let q=session[position];$('progress').textContent=`問題 ${position+1} / ${session.length} ｜ 正解 ${correct}`;$('topic').textContent=q.topic;$('terminal').textContent=q.screen;$('question').textContent=q.q;$('feedback').classList.add('hidden');$('next').classList.add('hidden');$('options').replaceChildren();q.opts.forEach((s,i)=>{let b=document.createElement('button');b.textContent=`${'ABCD'[i]}  ${s}`;b.onclick=()=>answer(i);$('options').append(b)})}
function answer(i){if(answered)return;answered=true;let q=session[position],ok=i===q.a;if(ok)correct++;let h=history[q.id]||{attempts:0,wrong:0};h.attempts++;if(ok)h.wrong=0;else h.wrong++;history[q.id]=h;save();[...$('options').children].forEach((b,j)=>{b.disabled=true;if(j===q.a)b.classList.add('good');else if(j===i)b.classList.add('bad')});$('feedback').textContent=`${ok?'✅ 正解！':'📖 正解は '+ 'ABCD'[q.a]+'：'+q.opts[q.a]}\n${q.why}`;$('feedback').style.whiteSpace='pre-wrap';$('feedback').classList.remove('hidden');$('next').textContent=position===session.length-1?'結果を見る':'次の問題へ';$('next').classList.remove('hidden')}
$('start').onclick=start;$('next').onclick=()=>{position++;if(position<session.length)render();else{$('score').textContent=`${session.length}問中 ${correct}問正解。間違えた問題は「間違えた問題だけ」から復習できます。`;show('result')}};$('back').onclick=()=>{stats();show('home')};stats();if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(()=>{$('status').textContent='オフライン保存に対応しています。初回はオンラインで開いてください。'}).catch(()=>{$('status').textContent='オフライン保存はHTTPS公開後に有効になります。'})}
